new_fn = r'''
/*
 * Fast path for str.isalpha for NPY_UNICODE arrays. Avoids creating Python
 * string scalars for each element.
 */
static PyObject *
_unicode_isalpha(PyObject *NPY_UNUSED(dummy), PyObject *args)
{
    PyArrayObject *char_array = NULL;
    PyArrayObject *char_array_in = NULL;

    if (!PyArg_ParseTuple(args, "O!:_unicode_isalpha", &PyArray_Type, &char_array_in)) {
        return NULL;
    }

    if (PyArray_TYPE(char_array_in) != NPY_UNICODE) {
        PyErr_SetString(PyExc_TypeError, "_unicode_isalpha requires a unicode array");
        return NULL;
    }

    /* Make sure we have a contiguous C array we can iterate over. */
    char_array = (PyArrayObject *)PyArray_FromArray(
        char_array_in, NULL,
        NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (char_array == NULL) {
        return NULL;
    }

    npy_intp itemsize = PyArray_ITEMSIZE(char_array);
    npy_intp nchars = itemsize / 4;  /* UCS-4 */
    npy_intp n = PyArray_SIZE(char_array);
    npy_intp ndim = PyArray_NDIM(char_array);
    npy_intp *dims = PyArray_DIMS(char_array);

    PyArrayObject *result = (PyArrayObject *)PyArray_EMPTY(ndim, dims, NPY_BOOL, 0);
    if (result == NULL) {
        Py_DECREF(char_array);
        return NULL;
    }

    npy_uint32 *data = (npy_uint32 *)PyArray_DATA(char_array);
    npy_bool *out = (npy_bool *)PyArray_DATA(result);

    for (npy_intp i = 0; i < n; i++) {
        npy_uint32 *s = data + i * nchars;
        /* Find effective length (strip trailing zeros) */
        npy_intp len = nchars;
        while (len > 0 && s[len - 1] == 0) {
            len--;
        }
        if (len == 0) {
            out[i] = 0;
            continue;
        }
        npy_bool ok = 1;
        for (npy_intp j = 0; j < len; j++) {
            if (!Py_UNICODE_ISALPHA((Py_UCS4)s[j])) {
                ok = 0;
                break;
            }
        }
        out[i] = ok;
    }

    Py_DECREF(char_array);
    return (PyObject *)result;
}

